-- SME Hub: a catalogue of legal templates, bundles and subscriptions for startups and small businesses.
create table if not exists public.sme_products (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique,
  name text not null,
  category text not null,
  kind text not null default 'template' check (kind in ('template','bundle','subscription')),
  summary text,
  price_minor integer check (price_minor >= 0),
  currency text not null default 'NGN',
  cover_url text,
  status text not null default 'published' check (status in ('draft','published','archived')),
  position integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create trigger sme_products_updated_at before update on public.sme_products for each row execute function public.set_updated_at();
alter table public.sme_products enable row level security;
create policy "published sme products are public" on public.sme_products for select using (status = 'published' or public.is_admin());
create policy "admins manage sme products" on public.sme_products for all using (public.is_admin()) with check (public.is_admin());
grant select on public.sme_products to anon, authenticated;
grant all on public.sme_products to service_role;
on conflict (slug) do nothing;
